sp_widget.css:
.ibar-score-circle { width: 120px; height: 120px; border-radius: 50%; border: 4px solid $brand-primary; display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; background: rgba($brand-primary, 0.05); }
.ibar-score-value { font-size: 32px; font-weight: 700; color: $brand-primary; }
.progress { margin-bottom: 8px; }

sp_widget.script:
(function() {
  data.score = 0;
  data.breakdown = { questionnaire: 0, documents: 0, clarifications: 0 };
  data.applicationId = $sp.getParameter("app_id") || "";
  try {
    if (!data.applicationId) return;
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    if (!appGr.get(data.applicationId)) return;
    data.score = parseInt(appGr.getValue("readiness_score") || "0", 10);
    data.breakdown.questionnaire = parseInt(appGr.getValue("completion_percent") || "0", 10);
    data.breakdown.documents = 50; // Placeholder - calculated from doc validation
    data.breakdown.clarifications = 100; // Placeholder
  } catch (e) {
    gs.error("IBAR Readiness Score widget error: " + e.message);
  }
})();
